insert into public.questions
  (id, category, prompt, scene, scene_variant, options, correct_index, lead, explanation, trap, wrong_notes, macete_quote, macete_hint)
values
  ('cruzamento-direita', 'Preferência', 'Cruzamento sem placas e sem semáforo. Quem passa primeiro?', 'intersection', null, '["O carro maior","Quem chegou primeiro","O carro que vem pela direita","O mais rápido"]'::jsonb, 2, 'Mas tamanho não define preferência.', 'Sem placa e sem semáforo, quem vem pela sua direita passa primeiro. Só isso decide.', 'A prova adora citar caminhão e ônibus para você achar que porte manda.', '{"0":"Tamanho não define preferência.","1":"Essa não é a regra geral neste cenário.","3":"Velocidade não cria preferência."}'::jsonb, '"Sem placa? Olha pra direita."', 'Cinco palavras que resolvem toda questão de cruzamento sem sinalização.'),
  ('rotatoria-circulando', 'Preferência', 'Você vai entrar numa rotatória sem semáforo. Quem tem preferência: você ou quem já está circulando dentro dela?', 'generic', 'road', '["Você, porque chegou primeiro na entrada","Quem já está circulando dentro da rotatória","Quem sinalizar a seta primeiro","Depende de quem estiver mais à direita"]'::jsonb, 1, 'Mas "chegar primeiro na entrada" não é a regra.', 'Quem já está circulando dentro da rotatória tem prioridade sobre quem está entrando — é a mesma lógica de uma via já ocupada.', 'A prova tenta te fazer achar que quem chega primeiro na entrada tem prioridade. Não tem.', '{"0":"Chegar na entrada não dá prioridade sobre quem já circula.","2":"A seta avisa, mas não cria prioridade.","3":"Posição na entrada não é o critério dentro da rotatória."}'::jsonb, '"Já tá girando? Passa primeiro."', 'Quem circula dentro da rotatória sempre tem prioridade sobre quem quer entrar.'),
  ('via-preferencial', 'Preferência', 'Você sai de uma rua secundária com placa "Dê a preferência" para entrar numa avenida movimentada. O que fazer?', 'generic', 'sign', '["Entrar assim que possível, mesmo sem espaço livre","Ceder passagem a quem já circula na via e entrar só quando for seguro","Buzinar e entrar","Esperar um carro da avenida sinalizar para você"]'::jsonb, 1, 'Mas essa placa não é uma ordem para parar total — é para ceder.', 'A placa "Dê a preferência" exige ceder passagem a quem já circula na via preferencial, entrando somente quando estiver seguro.', 'A prova confunde essa placa com a de PARE — são regras diferentes.', '{"0":"Entrar sem espaço livre ignora quem já está circulando.","2":"Buzinar não transfere a preferência para você.","3":"Você não precisa de um sinal alheio para agir — a decisão é sua, com segurança."}'::jsonb, '"Dê a preferência? Você decide quando é seguro — nunca antes de quem já circula."', 'É sobre ceder, não sobre parar totalmente.'),
  ('cruzamento-pare', 'Preferência', 'Você chega a um cruzamento com placa de PARE. Não há nenhum veículo ou pedestre à vista. O que fazer?', 'generic', 'sign', '["Reduzir a velocidade e seguir, já que está vazio","Parar completamente antes de prosseguir","Parar só se vir outro carro se aproximando","Parar apenas se for período de aula"]'::jsonb, 1, 'Mas a placa PARE não é opcional mesmo com a via vazia.', 'A placa de PARE exige parada total e obrigatória, independentemente de haver ou não outros veículos visíveis no momento.', 'A prova testa se você acha que "rolar devagar" substitui parar — não substitui.', '{"0":"Reduzir não é o mesmo que parar completamente.","2":"A obrigação de parar não depende de haver outro carro por perto.","3":"A regra vale o tempo todo, não só perto de escolas."}'::jsonb, '"Placa de PARE? Roda zero, sempre."', 'Parada total é obrigatória mesmo com a via vazia.'),
  ('faixa-pedestre', 'Sinalização', 'Pedestre esperando para atravessar na faixa, sem semáforo. O que você faz?', 'generic', 'pedestrian', '["Buzinar e seguir","Parar e dar passagem","Acelerar antes que ele entre","Esperar ele gesticular"]'::jsonb, 1, 'Mas quem está a pé não precisa pedir passagem.', 'Faixa de pedestres sem semáforo: o pedestre tem prioridade assim que sinaliza a intenção de atravessar.', 'A prova sugere que "ele ainda não pisou na faixa" muda alguma coisa — não muda.', '{"0":"Buzinar não transfere a prioridade para você.","2":"Acelerar antes que ele entre é o oposto do que a lei exige.","3":"Você não precisa de um sinal dele para ceder a passagem."}'::jsonb, '"Pedestre na faixa? Ele manda."', 'Sem semáforo, quem está a pé sempre tem prioridade sobre quem está no veículo.'),
  ('proibido-parar-estacionar', 'Sinalização', 'Placa de "Proibido Parar" numa rua. Você pode parar alguns segundos só para um passageiro descer?', 'generic', 'sign', '["Sim, se for rápido","Não — parar ali é proibido em qualquer situação de trânsito","Sim, com o pisca-alerta ligado","Só se não vier nenhum carro atrás"]'::jsonb, 1, 'Mas "proibido parar" é diferente de "proibido estacionar".', '"Proibido Parar" veta a parada por qualquer motivo, mesmo rápido. Já "Proibido Estacionar" permite parar brevemente para embarque ou desembarque.', 'A prova troca essas duas placas de propósito — decore a diferença, não o desenho.', '{"0":"Rapidez não muda a proibição desta placa específica.","2":"Pisca-alerta não autoriza parar onde é proibido.","3":"A ausência de outros carros não altera a regra da placa."}'::jsonb, '"PARAR proíbe tudo. ESTACIONAR libera o rapidinho."', 'A palavra na placa é o que decide, não a pressa.'),
  ('semaforo-amarelo', 'Sinalização', 'O semáforo fica amarelo exatamente quando você já está passando pela faixa de retenção. O que fazer?', 'generic', 'signal', '["Frear bruscamente para não passar no amarelo","Concluir a travessia normalmente","Dar ré até a faixa","Acelerar ao máximo para escapar do vermelho"]'::jsonb, 1, 'Mas frear ali cria mais risco do que resolve.', 'Se você já ultrapassou a faixa de retenção quando o sinal muda para amarelo, o correto é concluir a travessia com segurança, sem frear bruscamente.', 'A prova testa se você confunde "amarelo" com "pare imediatamente", mesmo já estando sobre o cruzamento.', '{"0":"Frenagem brusca no meio do cruzamento aumenta o risco de colisão traseira.","2":"Dar ré em um cruzamento é ainda mais perigoso.","3":"Acelerar bruscamente não é a resposta correta e ainda é imprudente."}'::jsonb, '"Já tá no cruzamento? Termina de atravessar."', 'O amarelo avisa quem ainda não chegou na faixa, não quem já passou dela.'),
  ('faixa-dupla-continua', 'Sinalização', 'Duas faixas amarelas contínuas dividem a pista em sentidos opostos. Mesmo com boa visibilidade à frente, você pode ultrapassar?', 'generic', 'road', '["Sim, se não vier nenhum carro","Não — faixa dupla contínua proíbe ultrapassagem","Sim, apenas de dia","Sim, se o carro da frente for muito lento"]'::jsonb, 1, 'Mas a visibilidade boa não muda o que a marcação da pista já decidiu.', 'A linha dupla contínua é uma proibição de ultrapassagem independente da visibilidade — a sinalização da pista vale por si só.', 'A prova tenta te convencer que "dá pra ver longe" libera a manobra. A marcação da pista não depende disso.', '{"0":"A ausência de carros não revoga a proibição da marcação.","2":"A proibição vale de dia e de noite.","3":"Lentidão do carro da frente não anula a marcação da pista."}'::jsonb, '"Linha dupla contínua? Nem pensar."', 'A marcação da pista manda mais que a sua visibilidade no momento.'),
  ('ultrapassagem-curva', 'Circulação', 'Pista simples, você se aproxima de uma curva sem visibilidade do que vem no sentido contrário. Pode ultrapassar?', 'generic', 'road', '["Sim, se estiver com pressa","Sim, buzinando antes","Não — a visibilidade não permite avaliar o sentido contrário","Sim, se o carro da frente for lento"]'::jsonb, 2, 'Mas pressa não cria visibilidade.', 'Ultrapassagem exige enxergar a pista contrária livre até completar a manobra e voltar à faixa. Sem visibilidade, é proibida.', 'A prova insinua que a lentidão do carro da frente justifica o risco — não justifica.', '{"0":"Pressa não muda o risco da manobra.","1":"Buzinar não cria visibilidade nem afasta quem vem no sentido contrário.","3":"Carro lento na frente não altera a regra de visibilidade."}'::jsonb, '"Não vê o fim da curva? Não ultrapassa."', 'Sem visibilidade da pista contrária, a ultrapassagem é sempre proibida.'),
  ('mudanca-de-faixa', 'Circulação', 'Você quer mudar de faixa numa avenida com trânsito. Qual é a ordem correta?', 'generic', 'road', '["Mudar e só depois sinalizar","Sinalizar, checar retrovisores e o ponto cego, e então mudar","Buzinar e mudar direto","Mudar rápido para não perder o espaço"]'::jsonb, 1, 'Mas a ordem das ações é o que evita o acidente.', 'O correto é sinalizar com antecedência, verificar retrovisores e o ponto cego, e só então mudar de faixa com segurança.', 'A prova gosta de inverter a ordem das ações para ver se você percebe.', '{"0":"Sinalizar depois de já ter mudado não avisa ninguém a tempo.","2":"Buzinar substitui a sinalização, mas não os retrovisores.","3":"Velocidade na manobra não substitui a checagem de segurança."}'::jsonb, '"Sinaliza, olha, só depois muda."', 'A ordem das três ações é o que separa a manobra seguraa do acidente.'),
  ('faixa-esquerda-uso', 'Circulação', 'Numa rodovia de pista dupla, para que serve a faixa da esquerda?', 'generic', 'road', '["Para trafegar o tempo todo, se quiser","Somente para ultrapassar, retornando depois à direita","Para veículos mais rápidos apenas","Para caminhões em subida"]'::jsonb, 1, 'Mas "faixa rápida" não é a mesma coisa que "faixa de uso livre".', 'A faixa da esquerda em rodovias de pista dupla é destinada à ultrapassagem — depois de ultrapassar, o correto é retornar à faixa da direita.', 'A prova tenta te fazer achar que carro "mais rápido" pode ocupar a esquerda o tempo todo.', '{"0":"Ocupar a esquerda permanentemente atrapalha quem quer ultrapassar.","2":"A regra não depende da velocidade do veículo, mas da manobra de ultrapassagem.","3":"Faixa de subida para caminhões é outra sinalização, específica."}'::jsonb, '"Ultrapassou? Volta pra direita."', 'A faixa da esquerda é passagem, não morada.'),
  ('conversao-proibida', 'Circulação', 'Você quer virar à esquerda numa esquina, mas há uma placa proibindo essa conversão. O que fazer?', 'generic', 'sign', '["Virar mesmo assim se não houver fiscalização","Seguir em frente e buscar outra rota ou retorno permitido","Fazer a conversão em marcha lenta","Virar à esquerda usando a faixa da direita"]'::jsonb, 1, 'Mas a ausência de fiscalização não torna a manobra permitida.', 'Com a conversão proibida sinalizada, o correto é seguir em frente e buscar uma rota alternativa ou um retorno autorizado mais à frente.', 'A prova testa se você acha que "ninguém vendo" muda a regra. Não muda.', '{"0":"A fiscalização não define se a manobra é permitida.","2":"Fazer a manobra devagar não a torna permitida.","3":"Trocar de faixa não anula a proibição da placa."}'::jsonb, '"Placa proibiu? Segue em frente e procura outro caminho."', 'Conversão proibida é proibida, com ou sem ninguém olhando.'),
  ('velocidade-escola', 'Infrações', 'Você se aproxima de uma escola no horário de entrada e saída, sem placa de velocidade específica ali. O que fazer?', 'generic', 'sign', '["Manter a velocidade normal da via","Reduzir a velocidade e redobrar a atenção","Acelerar para passar rápido pela área de risco","Buzinar continuamente para avisar as crianças"]'::jsonb, 1, 'Mas "não ter placa" não significa "sem responsabilidade".', 'Perto de escolas, mesmo sem placa específica de velocidade, a lei espera redução de velocidade e atenção redobrada pela presença de crianças.', 'A prova sugere que sem placa não há dever nenhum — o dever de cuidado continua existindo.', '{"0":"Manter a velocidade normal ignora o risco maior da área.","2":"Acelerar na área de risco é o oposto do comportamento esperado.","3":"Buzinar não substitui reduzir a velocidade."}'::jsonb, '"Perto de escola? Pé leve, sempre."', 'Área escolar pede cautela mesmo sem placa dizendo isso.'),
  ('celular-dirigindo', 'Infrações', 'Parado num sinal vermelho, você quer checar uma notificação segurando o celular na mão. Isso é permitido?', 'generic', 'road', '["Sim, porque o carro está parado","Não — segurar o celular na mão é infração mesmo parado no trânsito","Sim, se for rápido","Sim, se usar viva-voz depois"]'::jsonb, 1, 'Mas "estar parado no sinal" não é a mesma coisa que "estar fora do trânsito".', 'Segurar e manusear o celular é infração mesmo com o veículo parado no trânsito, como num semáforo — a proibição é sobre o ato de segurar o aparelho.', 'A prova tenta te convencer que estar parado muda a regra. Não muda.', '{"0":"O veículo parado no fluxo do trânsito ainda conta como \"dirigindo\" para essa regra.","2":"A duração do uso não altera a infração.","3":"Usar viva-voz depois não desfaz o ato de segurar o aparelho antes."}'::jsonb, '"No trânsito, celular na mão é sempre infração."', 'Parado no sinal ainda é trânsito — a mão no celular é o problema.'),
  ('cinto-passageiro', 'Infrações', 'Um passageiro do banco de trás se recusa a usar o cinto de segurança. De quem é a responsabilidade nessa infração?', 'generic', 'road', '["Só do passageiro, já que é decisão dele","Do condutor, responsável por garantir o uso do cinto por todos os ocupantes","De ninguém, no banco de trás o cinto é opcional","Só se o passageiro for menor de idade"]'::jsonb, 1, 'Mas "decisão do passageiro" não tira a responsabilidade de quem dirige.', 'O condutor é responsável por assegurar que todos os ocupantes do veículo, inclusive no banco de trás, estejam usando o cinto de segurança.', 'A prova sugere que o banco de trás "conta menos" — não conta menos.', '{"0":"A responsabilidade formal recai também sobre o condutor.","2":"O cinto é obrigatório em todos os bancos, inclusive no de trás.","3":"A obrigatoriedade vale para adultos e crianças."}'::jsonb, '"Cinto de todo mundo é problema seu, motorista."', 'A responsabilidade pelos ocupantes é do condutor, banco da frente ou de trás.'),
  ('embriaguez-limite', 'Infrações', 'Você bebeu uma única cerveja e vai dirigir uma distância curta até em casa. Isso é permitido?', 'generic', 'road', '["Sim, porque foi só uma dose","Não — a tolerância de álcool para dirigir no Brasil é praticamente zero","Sim, se a distância for curta","Sim, se dirigir bem devagar"]'::jsonb, 1, 'Mas "só uma dose" já pode configurar infração.', 'A legislação brasileira adota tolerância praticamente zero para álcool ao volante — mesmo pequenas quantidades podem gerar multa e outras penalidades.', 'A prova testa se você acha que "pouca quantidade" ou "trajeto curto" mudam a regra. Não mudam.', '{"0":"A quantidade não isenta da infração.","2":"A distância do trajeto não altera a regra.","3":"Dirigir devagar não compensa o efeito do álcool nem muda a lei."}'::jsonb, '"Bebeu? Não dirige. Ponto final."', 'A tolerância de álcool ao volante é praticamente zero, sem exceção por quantidade.'),
  ('chuva-distancia', 'Direção defensiva', 'Está chovendo forte na rodovia. O que muda na sua condução?', 'generic', 'weather', '["Nada, só ligar o limpador","Reduzir velocidade e aumentar a distância do carro da frente","Acender o pisca-alerta e manter a velocidade","Seguir mais perto para enxergar as luzes de freio"]'::jsonb, 1, 'Mas ficar colado no carro da frente piora, não ajuda.', 'Piso molhado aumenta a distância de frenagem. Reduzir a velocidade e abrir mais distância compensa isso.', 'A prova insinua que "ficar colado" ajuda a enxergar — na prática, aumenta o risco de colisão traseira.', '{"0":"O limpador resolve a visão, não a frenagem.","2":"Pisca-alerta em movimento confunde quem vem atrás.","3":"Ficar mais perto reduz seu tempo de reação, não aumenta."}'::jsonb, '"Chuva? Menos velocidade, mais distância."', 'A combinação que evita aquaplanagem e colisão traseira.'),
  ('distancia-seguranca-seca', 'Direção defensiva', 'Em pista seca, qual é uma forma prática de manter distância segura do carro da frente?', 'generic', 'road', '["Ficar o mais perto possível para não perder a vaga na fila","Contar cerca de 2 segundos entre o carro da frente passar por um ponto fixo e você passar pelo mesmo ponto","Olhar só a velocidade no painel","Manter distância fixa de um metro, sempre"]'::jsonb, 1, 'Mas distância "de olho" muda com a velocidade — por isso a regra dos segundos funciona melhor.', 'A regra prática dos 2 segundos entre um ponto fixo e a passagem do seu carro garante uma distância proporcional à velocidade atual.', 'A prova tenta vender a ideia de "distância fixa em metros" como solução universal — não é, porque a velocidade muda o cálculo.', '{"0":"Ficar colado reduz seu tempo de reação a quase zero.","2":"A velocidade no painel sozinha não informa a distância real do carro da frente.","3":"Distância fixa em metros ignora a velocidade — o correto é pensar em tempo, não só espaço."}'::jsonb, '"Conta 2 segundos do ponto fixo até você passar por ele."', 'Tempo de reação, não metros fixos, é o que garante distância segura.'),
  ('neblina', 'Direção defensiva', 'Você dirige numa rodovia com neblina densa, visibilidade muito reduzida. O que fazer?', 'generic', 'weather', '["Usar farol alto para enxergar mais longe","Reduzir a velocidade, usar farol baixo/neblina e aumentar a distância","Manter a velocidade e seguir as luzes do carro da frente","Desligar os faróis para não refletir na neblina"]'::jsonb, 1, 'Mas farol alto na neblina faz o oposto do que parece.', 'Na neblina, o correto é reduzir a velocidade, usar farol baixo ou de neblina, e aumentar a distância — farol alto reflete na névoa e piora a visão.', 'A prova conta com a intuição errada de que "farol alto sempre ajuda a ver mais". Na neblina, atrapalha.', '{"0":"O farol alto reflete na neblina e reduz ainda mais a visibilidade.","2":"Seguir as luzes do carro da frente sem reduzir velocidade é arriscado.","3":"Desligar os faróis torna você invisível para os outros veículos."}'::jsonb, '"Neblina? Farol baixo, nunca alto."', 'O farol alto reflete na névoa — o baixo é o que realmente ajuda a enxergar e ser visto.'),
  ('sono-ao-volante', 'Direção defensiva', 'Numa viagem longa, você sente sono forte enquanto dirige. O que fazer?', 'generic', 'road', '["Abrir o vidro e ligar o som mais alto para espantar o sono","Parar em local seguro e descansar antes de continuar","Continuar dirigindo mais devagar","Beber um energético e seguir no mesmo ritmo"]'::jsonb, 1, 'Mas nenhum truque substitui descanso de verdade.', 'Sono ao volante exige parar em local seguro para descansar — dirigir cansado reduz drasticamente o tempo de reação, mesmo em velocidade menor.', 'A prova sugere pequenos truques (som alto, vidro aberto, energético) como solução — nenhum deles resolve o sono de verdade.', '{"0":"Som alto e vento dão uma sensação passageira, não resolvem o sono.","2":"Dirigir mais devagar cansado ainda é perigoso.","3":"Energético não substitui o descanso, só mascara o cansaço por pouco tempo."}'::jsonb, '"Sono no volante? Para o carro, não a viagem."', 'Só descanso de verdade resolve sono — o resto é ilusão temporária.'),
  ('acidente-sinalizar', 'Primeiros socorros', 'Você chega perto de um acidente na estrada. Qual é o primeiro passo antes de socorrer as vítimas?', 'generic', 'sign', '["Correr direto para ajudar as vítimas","Sinalizar o local para evitar novos acidentes","Filmar a cena para acionar o seguro depois","Buzinar para os outros carros desviarem"]'::jsonb, 1, 'Mas socorrer sem proteger o local pode criar uma segunda tragédia.', 'Antes de socorrer, é essencial sinalizar o local do acidente, protegendo você, as vítimas e outros motoristas de um novo acidente.', 'A prova testa o impulso de "ajudar primeiro" sem considerar a segurança da cena.', '{"0":"Correr sem sinalizar coloca você e as vítimas em risco de outro impacto.","2":"Filmar antes de sinalizar prioriza o errado.","3":"Buzinar sozinho não sinaliza o local de forma segura."}'::jsonb, '"Sinaliza antes de socorrer."', 'Proteger a cena vem antes de qualquer atendimento.'),
  ('vitima-consciente', 'Primeiros socorros', 'Uma vítima de acidente está consciente, mas se queixa de dor forte no pescoço. O que fazer?', 'generic', 'road', '["Movê-la com cuidado para um lugar mais confortável","Não mover a vítima e acionar o socorro especializado","Ajudá-la a ficar em pé para ver se anda","Retirar qualquer peça de roupa apertada no pescoço"]'::jsonb, 1, 'Mas "com cuidado" não elimina o risco de mover alguém com possível lesão na coluna.', 'Diante da suspeita de lesão na coluna ou pescoço, a orientação é não mover a vítima e acionar o socorro especializado imediatamente.', 'A prova sugere boas intenções (mover com cuidado, ajudar a levantar) que na prática podem agravar uma lesão de coluna.', '{"0":"Mesmo com cuidado, mover pode agravar uma possível lesão na coluna.","2":"Colocar a vítima em pé é especialmente arriscado nesse cenário.","3":"Manipular a região do pescoço sem preparo pode piorar a lesão."}'::jsonb, '"Dor no pescoço? Não move, chama o socorro."', 'Suspeita de lesão na coluna significa: não mexa, acione ajuda especializada.'),
  ('capacete-motociclista', 'Primeiros socorros', 'Um motociclista caiu e está caído, ainda com o capacete. Você deve retirar o capacete dele?', 'generic', 'road', '["Sim, sempre, para ele respirar melhor","Não retirar, a menos que esteja impedindo a respiração","Sim, para verificar se está sangrando","Não, e também não se deve chamar o socorro"]'::jsonb, 1, 'Mas "para respirar melhor" é justamente o único motivo que justificaria mexer no capacete.', 'O capacete só deve ser retirado se estiver impedindo a respiração da vítima — caso contrário, mexer nele pode agravar uma possível lesão na coluna cervical.', 'A prova conta com o instinto de "tirar o capacete para ajudar" — que, sem necessidade real, pode piorar tudo.', '{"0":"Retirar sempre, sem necessidade, aumenta o risco de lesão na coluna.","2":"Verificar sangramento não exige remover o capacete inteiro.","3":"O socorro deve sempre ser acionado, independente do capacete."}'::jsonb, '"Capacete só sai se travar a respiração."', 'Mexer sem necessidade arrisca a coluna cervical da vítima.'),
  ('numero-emergencia', 'Primeiros socorros', 'Você presencia um acidente e precisa acionar uma ambulância. Qual número chamar?', 'generic', 'sign', '["190","192","191","199"]'::jsonb, 1, 'Mas 190 é a Polícia Militar, não a ambulância.', 'O número 192 aciona o SAMU, o serviço de atendimento móvel de urgência responsável pelo resgate e primeiros socorros.', 'A prova mistura números de serviços diferentes de propósito — cada um atende uma urgência distinta.', '{"0":"190 é o número da Polícia Militar.","2":"191 não é um número de emergência padrão para esse serviço.","3":"199 é o número da Defesa Civil, não do resgate médico."}'::jsonb, '"192 é ambulância. Decorou, não erra mais."', 'Cada número de emergência tem um serviço específico — memorize o 192 para resgate.')
